package io.nebulaflow.runner;
import io.nebulaflow.engine.DagPlanner; import io.nebulaflow.rag.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public class RagIngestTaskRunner implements TaskRunner { private final RagService service; public RagIngestTaskRunner(RagService service){this.service=service;} public String type(){return "RAG_INGEST";}
 public Object run(DagPlanner.Node node,Map<String,Object> context,TaskContext task){Map<String,Object> c=node.config();String collection=str(c.getOrDefault("collection","default"),"collection");Object raw=c.get("documents");if(raw==null)raw=task.input().get("documents");List<Map<String,Object>> docs=new ArrayList<>();if(raw instanceof List<?> list)for(Object x:list)docs.add(map(x,"document"));else {Map<String,Object> one=new LinkedHashMap<>();one.put("documentId",c.getOrDefault("documentId",node.id()));one.put("text",c.getOrDefault("text",task.input().get("text")));one.put("metadata",c.getOrDefault("metadata",task.input().get("metadata")));docs.add(one);}List<Map<String,Object>> result=new ArrayList<>();for(Map<String,Object>d:docs){var r=service.ingest(task.tenantId(),collection,new RagModels.Document(str(d.getOrDefault("documentId",node.id()),"documentId"),str(d.get("text"),"text"),map(d.get("metadata"),"metadata")),integer(c.get("chunkSize")),integer(c.get("chunkOverlap")));result.add(Map.of("documentId",r.documentId(),"chunks",r.chunks()));}return Map.of("collection",collection,"documents",result);}
 private static Map<String,Object> map(Object x,String label){if(x==null)return Map.of();if(!(x instanceof Map<?,?> raw))throw new IllegalArgumentException(label+" must be an object");Map<String,Object> r=new LinkedHashMap<>();raw.forEach((k,v)->r.put(String.valueOf(k),v));return r;} private static String str(Object x,String n){if(x==null||String.valueOf(x).isBlank())throw new IllegalArgumentException(n+" is required");return String.valueOf(x);} private static Integer integer(Object x){if(x==null)return null;if(!(x instanceof Number n))throw new IllegalArgumentException("chunk settings must be numeric");return n.intValue();} }